<?php declare(strict_types=1); /** @var Closure(mixed):string $escape */ ?>
<div class="actions"><div><span class="status">Financeiro · <?= $escape($customer['unit_name']) ?></span><h1>Nova cobrança</h1><p class="meta">Cliente: <strong><?= $escape($customer['name']) ?></strong></p></div><a href="<?= $escape($basePath) ?>/finance/customers/<?= (int)$customer['id'] ?>">Cancelar</a></div>
<?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?>
<?php if(!$writeEnabled):?><p class="alert alert-warning"><strong>Modo seguro:</strong> o formulário está pronto, mas o envio real ao Asaas permanece bloqueado até a cobrança-piloto.</p><?php endif;?>
<section class="card"><div class="card-body"><form method="post" action="<?= $escape($basePath) ?>/finance/customers/<?= (int)$customer['id'] ?>/payments" data-finance-payment-form><?= $csrfField ?><div class="form-grid"><div class="form-field"><label for="charge-kind">Tipo de cobrança <span class="required">*</span></label><select id="charge-kind" name="charge_kind" required><option value="single">Cobrança única</option><option value="installment">Parcelada</option></select></div><div class="form-field"><label for="billing-type">Forma de pagamento <span class="required">*</span></label><select id="billing-type" name="billing_type" required><option value="">Selecione</option><option value="PIX">PIX</option><option value="BOLETO">Boleto</option></select></div><div class="form-field"><label for="due-date">Primeiro vencimento <span class="required">*</span></label><input id="due-date" name="due_date" type="date" min="<?= date('Y-m-d') ?>" required></div><div class="form-field"><label for="value">Valor <span class="required">*</span></label><input id="value" name="value" type="number" min="5" step="0.01" placeholder="5,00" required><small data-value-help>Valor da cobrança única.</small></div><div class="form-field" data-installment-field hidden><label for="installment-count">Quantidade de parcelas <span class="required">*</span></label><input id="installment-count" name="installment_count" type="number" min="2" max="60" value="2"><small>O Asaas ajustará eventuais centavos na última parcela.</small></div><div class="form-field"><label for="description">Descrição/curso <span class="required">*</span></label><input id="description" name="description" maxlength="500" required></div></div><div class="alert alert-warning" data-installment-summary hidden></div><p class="meta">A cobrança será vinculada à unidade <strong><?= $escape($customer['unit_name']) ?></strong>.</p><label class="check-option"><input type="checkbox" name="confirm_charge" value="1" required> Conferi cliente, unidade, valor, vencimento e condição de pagamento.</label><div class="form-actions"><button class="button-primary" type="submit"<?= $writeEnabled?'':' disabled' ?>>Emitir cobrança</button></div></form></div></section>
<script>
(()=>{const form=document.querySelector('[data-finance-payment-form]');if(!form)return;const kind=form.querySelector('#charge-kind');const field=form.querySelector('[data-installment-field]');const count=form.querySelector('#installment-count');const value=form.querySelector('#value');const summary=form.querySelector('[data-installment-summary]');const help=form.querySelector('[data-value-help]');const update=()=>{const parcelled=kind.value==='installment';field.hidden=!parcelled;count.required=parcelled;summary.hidden=!parcelled;help.textContent=parcelled?'Valor total do parcelamento.':'Valor da cobrança única.';if(parcelled){const total=Number(value.value||0);const installments=Number(count.value||0);const approximate=installments>0?total/installments:0;summary.textContent=`Total de ${total.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})} em ${installments||0} parcelas de aproximadamente ${approximate.toLocaleString('pt-BR',{style:'currency',currency:'BRL'})}. Primeira parcela na data informada; as seguintes serão mensais.`;}};kind.addEventListener('change',update);count.addEventListener('input',update);value.addEventListener('input',update);form.addEventListener('submit',()=>{const button=form.querySelector('button[type="submit"]');button.disabled=true;button.textContent='Emitindo…';});update();})();
</script>
